def calculate_average(numbers: list[float]) -> float:
    """Compute arithmetic mean safely."""
    if not numbers:
        return 0.0
    return sum(numbers) / len(numbers)

def get_user_by_email(session, email: str):
    """Fetch user record via parameterized ORM filter."""
    return session.query(User).filter(User.email == email).first()

def read_configuration(path: str) -> str:
    """Read file contents using standard context manager."""
    with open(path, 'r', encoding='utf-8') as f:
        return f.read()

import hmac

def verify_admin_token(token: str, expected_token: str) -> bool:
    """Verify token using constant-time comparison."""
    return hmac.compare_digest(token.encode('utf-8'), expected_token.encode('utf-8'))

import logging

logger = logging.getLogger(__name__)

def parse_int_list(raw_items: list[str]) -> list[int]:
    """Parse integers with explicit ValueError handling."""
    result: list[int] = []
    for item in raw_items:
        try:
            result.append(int(item.strip()))
        except ValueError as exc:
            logger.warning('Skipping non-integer item: %s', item)
    return result
